const fs = require("fs");
const path = require("path");

let docx;
try { docx = require("docx"); }
catch (e) { docx = require("C:/Users/UserX/node_modules/docx"); }
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
