  AlignmentType, HeadingLevel, WidthType, BorderStyle, ShadingType,
  SectionType, TableOfContents,
} = docx;

const ROOT = path.resolve(__dirname, "..");
const FIG = path.join(ROOT, "results", "paper_figs");
const OUTFILE = path.join(ROOT, "黑青稞近红外毕业设计全面解析.docx");

// ---------------- CSV 读取工具 ----------------
function readCSV(fp) {
  const s = fs.readFileSync(fp, "utf-8");
  const lines = s.replace(/^\uFEFF/, "").trim().split(/\r?\n/);
  const rows = lines.map(l => l.split(","));
  return rows;
}
function meanStd(vals) {
  const m = vals.reduce((a, b) => a + b, 0) / vals.length;
  const varr = vals.reduce((a, b) => a + (b - m) * (b - m), 0) / (vals.length - 1);
  return [m, Math.sqrt(varr)];
}
function dlStats(tag, model, comp) {
  const rows = readCSV(path.join(ROOT, "results", "dl_compare", `${tag}_${model}.csv`));
  const head = rows[0];
  const iComp = head.indexOf("comp"), iR = head.indexOf("Rp"), iM = head.indexOf("RMSEP");
  const Rp = [], RM = [];
  for (const r of rows.slice(1)) if (r[iComp] === comp) { Rp.push(+r[iR]); RM.push(+r[iM]); }
  return [meanStd(Rp), meanStd(RM)];
}
function plsStats(tag, compZh) {
  const rows = readCSV(path.join(ROOT, "results", tag, "metrics_final.csv"));
  const head = rows[0];
  const iComp = head.indexOf("成分"), iModel = head.indexOf("模型"), iVars = head.indexOf("变量数"),
        iRc = head.indexOf("Rc"), iRmsec = head.indexOf("RMSEC"), iRp = head.indexOf("Rp"),
        iRmsep = head.indexOf("RMSEP"), iRpd = head.indexOf("RPD"), iStab = head.length - 1;
  for (const r of rows.slice(1)) {
    if (r[iComp] === compZh && r[iModel] === "CARS-PLS") {
      return { vars: r[iVars], rc: r[iRc], rmsec: r[iRmsec], rp: r[iRp], rmsep: r[iRmsep],
               rpd: r[iRpd], stabRp: r[11], stabRmsep: r[12] };
    }
  }
  return null;
}
const fmt = (v, n = 4) => Number(v).toFixed(n);
const fmtPair = (ms, n = 4) => `${fmt(ms[0], n)}±${fmt(ms[1], n)}`;

// ---------------- 通用构件 ----------------
const FONT_BODY = { ascii: "Times New Roman", eastAsia: "SimSun" };
const FONT_HEI = { ascii: "Times New Roman", eastAsia: "SimHei" };
const NB = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };

function body(text, opts = {}) {
  return new Paragraph({
    alignment: AlignmentType.JUSTIFIED,
