function bt(text) { return new TextRun({ text, size: 24, color: "000000", font: FONT_BODY }); }
function h1(text) {
  return new Paragraph({ heading: HeadingLevel.HEADING_1, alignment: AlignmentType.CENTER,
    spacing: { before: 480, after: 360, line: 360 },
