}
function h3(text) {
  return new Paragraph({ heading: HeadingLevel.HEADING_3,
    spacing: { before: 240, after: 120, line: 360 },
    children: [new TextRun({ text, bold: true, size: 28, color: "000000", font: FONT_HEI })] });
}

// 图: 图题在下(宋体五号居中), 引用宽度 16cm≈605px(96dpi)
function figure(file, caption, pxH) {
  const buf = fs.readFileSync(path.join(FIG, file));
