{"content": "// gen_docx.js —— 主生成脚本(正文内容)
const L = require("./lib.js");
const {
  Document, Packer, Paragraph, TextRun, PageBreak, Header, Footer, PageNumber,
  NumberFormat, AlignmentType, HeadingLevel, SectionType, TableOfContents,
  FONT_BODY, FONT_HEI, body, bodyRuns, bt, h1, h2, h3, figure, threeLine,
  buildHeader, buildFooter, buildAcademicCover, fs, path, ROOT, OUTFILE,
  readCSV, dlStats, plsStats, fmt, fmtPair, cornF, qkF,
} = L;

const TITLE = "基于近红外光谱的黑青稞水分、淀粉、蛋白质无损检测毕业设计全面解析";

// ================= 摘要 =================
function buildAbstract() {
  return [
    h1("摘　要"),
    body("黑青稞是青藏高原特色杂粮作物，其水分、淀粉和蛋白质含量直接决定储藏安全、加工适性与营养价值，传统理化检测耗时长、消耗试剂且破坏样品。本报告面向基于近红外光谱（NIR）与化学计量学的黑青稞三组分无损检测毕业设计，从选题背景、方法选型、实验方案、代码复现到论文答辩给出全流程解析。"),
    body("针对近红外技术是否过时、是否应采用神经网络建模、是否已有青稞光谱数据三个疑问，本报告以 2023—2026 年文献和国家标准为证据逐一排查：近红外是现行粮食行业的标准方法（GB/T 24895、GB/T 24896 等标准体系），并非过时技术；深度学习建模通常需要千级以上样本才能稳定优于偏最小二乘（PLS），在 60～135 个样本的毕业设计规模下 PLS 是正确的主模型选择；青稞近红外研究已有报道（如 2025 年发表于 Journal of the Science of Food and Agriculture 的青稞五参数近红外定量研究），但均未公开数据集，黑粒色品种的专门定标研究仍属空白，自建数据集具有明确价值。"),
    body("在复现层面，本报告构建了双轨验证体系：以 Eigenvector 官方玉米基准真实数据（80 个样本，含水、蛋白质、淀粉参考值）验证 SPXY 划分、NIPALS 偏最小二乘、CARS 变量筛选等全链算法的正确性，三组分预测相关系数分别达到 1.000、0.989、0.966，与已发表文献量级一致；按文献成分范围与吸收峰归属构建 180 个样本的黑青稞物理仿真数据集演示完整毕业设计流程，CARS 筛选出的特征波长精准命中预先埋入的水（1450、1940 nm）、蛋白质（2050、2180 nm）、淀粉（2100、2270、2324 nm）吸收带。在相同划分协议下实测对比 CARS-PLS、支持向量回归与一维卷积神经网络三种模型，结果表明小样本条件下 PLS 全面占优，为建模方法选型提供了数据支撑。全部代码、数据与图表可一键复现。"),
    bodyRuns([
      new TextRun({ text: "关键词：", bold: true, size: 24, font: FONT_HEI, color: "000000" }),
      new TextRun({ text: "近红外光谱；黑青稞；化学计量学；偏最小二乘；竞争性自适应重加权采样；无损检测", size: 24, font: FONT_BODY, color: "000000" }),
    ]),
  ];
}

// ================= 第一章 =================
function buildCh1() {
  const out = [];
  out.push(h1("第一章　选题背景与技术研究现状"));
  out.push(h2("1.1　黑青稞及其品质指标"));
  out.push(body("青稞（hulless barley，裸大麦 Hordeum vulgare var. nudum）是青藏高原对裸大麦的通称，籽粒成熟后颖壳自然脱落、裸粒收获，在高原种植已有约 3500 年历史，是藏区主粮与青稞酒、糌粑等加工品的原料。黑青稞指种皮富集花青素而呈黑紫色的一类特色品种。文献报道的成分范围：总淀粉约占籽粒质量的 47.9%～79.0%，蛋白质 6.35%～21.0%（黑青稞品种实测 12.19%～14.07%），储藏水分一般要求不超过 13%。"));
  out.push(body("三个指标各有明确的产业意义：水分决定储藏安全与粉碎性能；淀粉总量及其直链/支链比例决定糌粑口感与酿酒得率；蛋白质决定营养价值与面制品加工适性。三者的现行测定方法均为破坏性化学实验：水分采用直接干燥法（GB 5009.3），蛋白质采用凯氏定氮法（GB 5009.5），淀粉采用酶水解法（GB 5009.9），单样品三指标测定需一个工作日，且样品被销毁，无法满足收粮定价、育种中间世代筛选与在线质控的时效要求。"));
  out.push(h2("1.2　近红外技术的现状：不是过时，而是行业标准"));
  out.push(body("近红外无损检测是否过时，判断依据不在论文数量，而在标准体系与产业应用。检索结果表明，近红外分析已进入我国粮食行业标准体系：GB/T 24895-2010 规定了粮油近红外定标模型验证与网络管理的通用规则，GB/T 24896-2010 规定了粮食水分近红外测定的性能要求（扣除系统偏差后标准差不大于 0.20%），GB/T 40467-2021 将近红外法通则扩展到畜禽肉品质检测。标准的存在意味着该方法已被行业接受为可仲裁、可传递的正规手段，这是过时技术不具备的地位。"));
  out.push(body("产业侧，FOSS 等厂商的近红外谷物分析仪已在粮食收购环节规模化配置，其全球共享定标网络基于超过五万个样本的_ann_定标模型；2024—2025 年的研究热点集中在定标模型传递、深度学习化学计量学与多组分在线检测。学术侧，2025 年《食品科学》刊出的谷物近红外检测综述系统总结了该方向的持续进展。结论：近红外技术处于成熟应用与方法演进并行的阶段，毕业设计选题不存在技术过时问题。"),);
  out.push(...threeLine("表 1-1　近红外在粮食行业中的标准与产业现状证据",
    ["证据类型", "具体内容", "来源"],
    [
      ["国家标准", "GB/T 24895-2010 定标模型验证与网络管理通用规则", "国家标准全文公开系统"],
      ["国家标准", "GB/T 24896-2010 粮食水分近红外测定(SEP≤0.20%)", "国家标准全文公开系统"],
      ["国家标准", "GB/T 40467-2021 畜禽肉品质检测近红外法通则", "国家标准化管理委员会"],
      ["产业应用", "近红外谷物分析仪用于收粮现场蛋白/水分定价, 全球共享定标网络(5万+样本)", "FOSS 等厂商公开资料"],
      ["研究热点", "定标传递、深度学习化学计量学、多组分在线检测(2024—2025)", "谷物近红外综述文献"],
    ], [16, 56, 28], "left"));
  out.push(h2("1.3　建模方法演进：为什么主线仍是 PLS，深度学习放在什么位置"));
  out.push(body("化学计量学建模方法的演进是本设计方法选型的核心问题。Mishra 与 Passos 2022 年发表于 Trends in Analytical Chemistry 的综述系统评估了深度学习用于近红外光谱建模的收益与炒作成分，核心结论是：深度学习通常需要一千至两千个以上样本才能稳定优于经典方法，小样本条件下偏最小二乘与支持向量机表现相当或更优；土壤近红外的学习曲线研究同样显示约一千个样本以下偏最小二乘占优。原因在于深度网络缺乏光谱数据的归纳偏置——它必须自行学习相邻波长高度相关、有效信息集中于若干吸收带这类先验结构，而样本不足时这种学习无法完成。"));
  out.push(body("偏最小二乘天然携带这种结构：潜变量本身就是对共线波长的最优线性压缩，配合 CARS 等显式变量筛选，把注意力直接放到化学吸收带上。2023 年以后的新进展并未推翻这一格局，而是给出补充路径：迁移学习与光谱基础模型（如预训练卷积网络的迁移策略研究、UltraIR 等大规模红外预训练模型）可将目标域样本需求降至几十至几百个，属于数据规模受限时引入外部先验的思路。对本设计 80～150 个样本的规模，合理结构是：PLS 为主线模型，支持向量机与一维卷积神经网络作为对比章节，迁移学习作为展望。本报告第五章在该协议下完成了三种模型的实测对比，结果支持上述选型。"));
  out.push(h2("1.4　已有青稞研究排查与本研究定位"));
  out.push(body("围绕是否早有黑青稞光谱数据的疑问，检索排查结论如下：近红外技术确已在青稞研究中使用，但形式与目的各异，且没有任何研究公开光谱数据集。最近似的研究是 2025 年发表于 Journal of the Science of Food and Agriculture 的青稞多参数近红外无损检测研究，覆盖总淀粉、直链淀粉、蛋白质、β-葡聚糖、总酚五个参数，比较了六种预处理并用 CARS 与 SPA 筛选特征波长，与本题技术路线高度同构；西藏自治区农牧科学院曾用近红外分析仪对 2011 份西藏野生大麦资源做营养品质评价，属于种质资源筛选而非定标建模；大麦近红外定标另有 Sohn 等 2007、2008 年的粉碎样与整粒研究。"));
  out.push(...threeLine("表 1-2　青稞/大麦近红外已有研究排查结论",
    ["研究", "内容与形式", "数据是否公开"],
    [
      ["Li 等, 2025 (JSFA)", "青稞五参数(总淀粉/直链淀粉/蛋白/β-葡聚糖/总酚)近红外定量, 六种预处理+CARS/SPA", "未公开"],
      ["西藏农牧科学院", "2011 份西藏野生大麦资源近红外品质评价(种质筛选)", "未公开"],
      ["Sohn 等, 2007/2008", "大麦粉碎样与整粒近红外定标(蛋白质/水分/淀粉等)", "未公开"],
