{"content": "// gen_docx.js —— 黑青稞近红外毕业设计全面解析(教学解析版)
const L = require("./lib.js");
const {
  Document, Packer, Paragraph, TextRun, AlignmentType, SectionType,
  TableOfContents, NumberFormat, FONT_BODY, FONT_HEI,
  BLUE, INK, MUTED, body, lead, bt, blue, h1, h2, h3, box, numList, numConfigs,
  bullets, figure, dataTable, buildHeader, buildFooter, buildCoverR4,
  fs, path, ROOT, OUTFILE, dlStats, plsStats, fmt, fmtPair,
} = L;

const TITLE = "黑青稞近红外毕业设计全面解析";

// =============== 导读 ===============
function buildIntro() {
  const out = [];
  out.push(h1("导读：这份解析怎么用"));
  out.push(body([bt("你的毕业设计题目是：用近红外光谱（NIR）加化学计量学，无损检测黑青稞的水分、淀粉、蛋白质含量。"),
    bt("这份解析不是替你写论文，而是把整道题拆开讲清楚：题目在问什么、每个方法为什么存在、每一步具体怎么做、哪些坑会扣分、以及所有结论的真实数据证据。配套代码和数据在本目录下，全部可一键复现。")]));
  out.push(...dataTable("表 1　全解析地图",
    ["部分", "回答的问题", "你该做什么"],
    [
      ["第 1 部分 看懂题目", "这道题到底在做什么? 为什么值得做? 难在哪?", "开题报告的素材来源"],
      ["第 2 部分 方法六讲", "每个算法解决什么问题? 参数怎么定?", "答辩被追问原理时不慌"],
      ["第 3 部分 操作卡", "八步任务每一步怎么做、怎么自查?", "照卡执行实验"],
      ["第 4 部分 疑问排查", "NIR 过时吗? 为什么不用神经网络? 有人做过吗?", "回应自己与评委的质疑"],
      ["第 5 部分 复现证据", "整条流水线跑出来的真实结果长什么样?", "对照自己的实验进度"],
      ["第 6 部分 论文与答辩", "论文怎么组织? 评委爱问什么?", "写作与答辩准备"],
    ], [22, 44, 34]));
  out.push(...box("tip", "三个使用建议", [
    "赶时间：先读第 1 部分和第 3 部分，能直接开干。",
    "要写开题：第 1 部分加第 4 部分的排查结论拼起来就是文献综述骨架。",
    "所有数字都来自 2026-10-24 在本机跑出的真实结果，代码入口见附录 A。",
  ]));
  return out;
}

// =============== 第 1 部分 ===============
function buildPart1() {
  const out = [];
  out.push(h1("第 1 部分　把题目看懂"));
  out.push(lead("这一部分回答：黑青稞是什么、为什么要测这三个指标、近红外凭什么能测、难点到底难在哪。读完你可以把题目讲给外行听。"));

  out.push(h2("1.1　一句话拆解题目"));
  out.push(...dataTable("表 1-1　题目要素拆解",
    ["要素", "内容", "一句话解释"],
    [
      ["研究对象", "黑青稞籽粒", "青藏高原特色杂粮, 种皮富花青素呈黑紫色"],
      ["要测什么", "水分 / 淀粉 / 蛋白质", "决定储藏、加工、营养的三项核心品质"],
      ["用什么测", "近红外光谱 (NIR)", "让光照一下整粒籽粒, 从光谱反推含量"],
      ["怎么反推", "化学计量学建模", "从一批光谱+化学值已知的样本里学出换算关系"],
      ["无损含义", "样品不破坏", "测完的籽粒还能发芽、还能磨粉卖"],
    ], [16, 30, 54]));

  out.push(h2("1.2　三个指标为什么值得测"));
  out.push(body([bt("现行测定方法全是破坏性化学实验："),
    bt("水分要 105 ℃ 烘几小时（GB 5009.3 直接干燥法），蛋白质要浓硫酸消解加蒸馏滴定（GB 5009.5 凯氏定氮），淀粉要酶水解再测糖（GB 5009.9）。"),
    bt("一个样品三指标测完要一个工作日，样品磨碎销毁。收粮定价、育种筛选、生产线质控都等不起。")]));
  out.push(...dataTable("表 1-2　三指标的产业意义与文献含量范围",
    ["指标", "决定什么", "文献范围", "现行方法痛点"],
    [
      ["水分", "储藏安全(≤13%防霉变)、粉碎性能", "约 7%~13%", "烘干数小时"],
      ["总淀粉", "糌粑口感、酿酒得率", "47.9%~79.0%", "酶水解流程最长"],
      ["蛋白质", "营养价值、加工适性", "6.35%~21.0%", "凯氏定氮用强酸强碱"],
    ], [14, 36, 22, 28]));
  out.push(...box("tip", "范围数据的出处", [
    "总淀粉范围来自甘孜州 31 个青稞品种实测；蛋白质总范围与黑青稞实测 12.19%~14.07% 来自《核农学报》2021 年青海黑青稞分析。仿真数据集的参数设定即取自这两篇，见第 5 部分。",
  ]));

  out.push(h2("1.3　近红外凭什么能测成分"));
  out.push(body([bt("物理内核一句话："), bt("分子里的化学键像弹簧连着小球，O-H、C-H、N-H 每种键振动的固有频率不同；近红外光（800~2500 nm）恰好能让这些键发生振动跃迁，键越多吸得越多，特定波长处光就变弱——变弱的多少与该成分含量近似成正比。")]));
  out.push(body([bt("中红外峰尖锐可鉴定物质，近红外峰弱而宽、严重重叠，做鉴定不行，"),
    bt("做定量反而合适"), bt("——峰面积与含量近似线性，混合物不用分离就能一起测。三个目标成分的指纹波长（记住这七个数，第 5 部分 CARS 筛出的波长会一个个落回来）：")]));
  out.push(...bullets([
    [bt("水分：", { bold: true }), bt("1450 nm（O-H 一级倍频）、1940 nm（合频，全谱最强峰）")],
    [bt("蛋白质：", { bold: true }), bt("2050、2180 nm（N-H、酰胺键）")],
    [bt("淀粉：", { bold: true }), bt("2100、2270、2324 nm（C-H / O-H）")],
  ]));
  out.push(...figure("figp_3_1_spectra.png", "图 1　玉米基准样品原始近红外光谱(细线为各样本, 粗线为均值; 竖虚线为三成分特征吸收带, 标签两行交错)", 755));
  out.push(body([bt("整粒籽粒是固体颗粒，光是弹回来的（漫反射）。颗粒大小、装样松紧、"),
    bt("深色种皮"), bt("都会让整条光谱整体抬高或压低——这就是散射。它比化学信号大得多却与成分无关。黑青稞种皮颜色深，散射比浅色谷物更凶。这是难点(1)的来源，也是预处理存在的理由。")]));

  out.push(h2("1.4　三个难点，每个都有对策"));
  out.push(...dataTable("表 1-3　难点与对策对照",
    ["任务书难点", "白话翻译", "对策", "在哪验证"],
    [
      ["种皮深、散射干扰明显", "光谱被物理干扰污染, 信号埋在噪声里", "SNV/MSC 散射校正 + 导数预处理, 逐一对比优选", "第 2.1 讲 / 第 5 部分"],
      ["多组分波段重叠", "蛋白峰和淀粉峰挤在一起, 肉眼分不开", "CARS 按成分分别筛选特征波长", "第 2.4 讲 / 第 5.3 节"],
