{"content": "// gen_repro.js —— 《青稞近红外论文复现全过程记录(小白版)》生成脚本
const L = require("./lib.js");
const {
  Document, Packer, Paragraph, TextRun, AlignmentType, SectionType,
  TableOfContents, NumberFormat, FONT_BODY, FONT_HEI,
  BLUE, INK, MUTED, body, lead, bt, blue, h1, h2, h3, box, numList, numConfigs,
  bullets, figure, dataTable, formula, where, buildHeader, buildFooter,
  buildCoverR4, fs, path, ROOT, fmt, fmtPair,
} = L;

const TITLE = "青稞近红外论文复现全过程记录";
const FIGDIR = path.join(ROOT, "results", "qingke76_paper");
const OUTFILE = path.join(ROOT, "青稞近红外论文复现全过程记录.docx");

// 本文档的图在 qingke76_paper 目录, 单独实现 figure(与 lib.figure 同规范)
function figure(file, caption) {
  const buf = fs.readFileSync(path.join(FIGDIR, file));
  const w = buf.readUInt32BE(16), h = buf.readUInt32BE(20);
  const W = 580, H = Math.round(W * h / w);
  return [
    new Paragraph({ alignment: AlignmentType.CENTER, keepNext: true,
      spacing: { before: 160, after: 60, line: 240, lineRule: "auto" },
      children: [new ImageRunLike(buf, W, H)] }),
    new Paragraph({ alignment: AlignmentType.CENTER,
      spacing: { after: 200, line: 300, lineRule: "auto" },
      children: [new TextRun({ text: caption, size: 19, color: MUTED, font: FONT_BODY })] }),
  ];
}
function ImageRunLike(buf, w, h) {
  const docx = L.docx;
  return new docx.ImageRun({ data: buf, transformation: { width: w, height: h }, type: "png" });
}

// CSV 读取
function readCSV(fp) {
  const rows = fs.readFileSync(fp, "utf-8").replace(/^\uFEFF/, "").trim().split(/\r?\n/).map(l => l.split(","));
  return rows;
}

// ================= 导读 =================
function buildIntro() {
  const out = [];
  out.push(h1("导读"));
  out.push(body([bt("这份记录回答一个问题：按已发表论文的方法，从数据到模型完整走一遍会经历什么、得到什么、与论文差在哪里。对象是两篇真实论文：杨焰婷等 2024 年发表于《食品工业科技》的青稞四成分 NIR 检测研究，与李苓蕾 2025 年天津科技大学硕士论文的青稞燕麦多指标研究。前者给出了完整的样本分布、参数与逐项结果数字，是本次复现的主参照。")]));
  out.push(...box("tip", "先说结论(三句话)", [
    "两篇论文的光谱与化学值原始数据均未公开, 因此本次做的是【流程复现】: 按论文公布的成分分布与光谱特征构造同分布仿真数据(76 份, 埋入 4 个异常样本), 严格按论文流程走一遍, 而不是复现论文的具体数字。",
    "流程每一步都真实跑通: 马氏距离剔除异常、六种预处理对比、SPXY 3:2 划分、CARS 与 SPA 特征筛选、PLS 建模; 预处理格局与论文一致(SG 平滑最优, SNV/MSC 单独使用对水分崩坏)。",
    "复现的 Rp(0.74~0.94)低于论文最优值(0.97~0.99), 差异原因在第四部分逐条分析——其中最重要的三条: 论文的增益主要来自 VCPA-IRIV 算法(未公开细节, 无法复现)、真实光谱的成分-光谱关系比理想仿真复杂、以及简化版 SPA 的局限。",
  ]));
  return out;
}

// ================= 第 1 部分 =================
function buildPart1() {
  const out = [];
  out.push(h1("第 1 部分　两篇论文讲了什么"));
  out.push(lead("先把两篇论文的方法与结论提炼成表格。它们的技术路线与你的毕业设计完全同构: 光谱采集 → 化学值测定 → 预处理 → 样本划分 → 特征波长筛选 → PLS 建模。"));

  out.push(h2("1.1　杨焰婷等 2024(主参照)"));
  out.push(...dataTable("表 1-1　杨焰婷论文关键信息",
    ["要素", "内容"],
    [
      ["样本", "76 份青稞(西藏/青海/甘肃/四川), 粉碎过 65 目筛"],
      ["仪器与光谱", "NIRFlex N500 傅里叶近红外, 透射, 4000~10000 cm-1(即 1000~2500 nm), 1501 个变量, 扫描 64 次平均, 每样 3 次平行"],
      ["化学值", "水分 GB 5009.3 直接干燥法; β-葡聚糖/直链淀粉 Megazyme 试剂盒; 蛋白质双缩脲法; 各 3 次平行取均值"],
      ["异常剔除", "马氏距离, 阈值 212.2, 剔除 4 个(48/49/53/57 号), 剩 72 个"],
      ["划分", "SPXY 按 3:2 → 43 校正 + 29 预测"],
      ["预处理", "SG / SNV / MSC / SG+MSC / MSC+SNV, 加原始共 6 种对比"],
      ["特征筛选", "CARS(100 轮蒙特卡洛, 5 折) / SPA / VCPA-IRIV"],
      ["含量分布(剔除后)", "水分 9.07~14.69(均值 10.77, SD 1.18); β-葡聚糖 3.33~8.97(4.55, 0.78); 直链淀粉 3.03~20.97(15.67, 3.14); 蛋白质 3.99~8.99(6.54, 1.33)"],
    ], [18, 82]));
  out.push(...dataTable("表 1-2　杨焰婷论文结果(表 3 与表 4 摘录)",
    ["成分", "最优预处理(全谱 PLS)", "全谱 Rp/RMSEP", "最优筛选方法", "筛选后 Rp/RMSEP", "变量数"],
    [
      ["水分", "SG", "0.9515 / 0.3914", "VCPA-IRIV", "0.9868 / 0.2042", "29"],
      ["β-葡聚糖", "SG", "0.9602 / 0.4102", "CARS", "0.9808 / 0.1846", "45"],
      ["直链淀粉", "SG", "0.9369 / 1.1747", "VCPA-IRIV", "0.9701 / 0.8135", "20"],
      ["蛋白质", "SG+MSC", "0.8356 / 0.7799", "VCPA-IRIV", "0.9879 / 0.2095", "52"],
    ], [14, 22, 22, 16, 18, 8]));
  out.push(...box("tip", "读这篇论文最值得注意的三点", [
    "SNV 与 MSC 单独使用时对水分几乎无效(Rp 0.36), 远差于 SG(0.95)——散射校正不是万能的, 与第 2.1 节的原理分析一致(水分是主信号, 归一化把水分信号一起归掉了)。",
    "论文的最大增益来自 VCPA-IRIV(蛋白质 Rp 从 0.84 提到 0.99), 而该算法的完整实现细节论文未公开——这是复现无法跨越的鸿沟, 详见第四部分。",
    "直链淀粉 RMSEP 0.81~2.29 看着大, 但其含量范围 3.03~20.97%(SD 3.14), 折算 RPD 仅 1.5~3.9——评价新指标时永远要先看含量范围。",
  ]));

  out.push(h2("1.2　李苓蕾 2025(方法参照)"));
  out.push(...dataTable("表 1-3　李苓蕾论文关键信息",
    ["要素", "内容"],
    [
      ["样本", "120 份青稞(青海 77/西藏 20/甘肃 23), 籽粒直接测量(不粉碎)"],
      ["仪器与光谱", "Si-Ware 手持式近红外(NeoSpectra), 1350~2500 nm; 另有第二台同型号仪器做主从传递"],
      ["化学值", "总淀粉/直链淀粉/蛋白质/β-葡聚糖/总酚(Megazyme 试剂盒、凯氏定氮、福林酚法)"],
      ["划分", "SPXY 按 4:1 → 96 校正 + 24 预测"],
      ["预处理", "SNV / MSC / 归一化 / 去趋势 / 一阶导 / 二阶导"],
      ["特征筛选", "CARS / SPA / UVE(无信息变量消除) / LAR(最小角回归)"],
      ["模型传递", "主从仪器间用 DS / PDS / DS-PDS 校正, 从仪器 Rp 大幅恢复(如总淀粉 0.435→0.903)"],
      ["最优结果", "总淀粉 DE-SPA Rp 0.956; 直链淀粉 Nor-CARS Rp 0.962; 蛋白质 SD-SPA Rp 0.936; β-葡聚糖 FD-CARS Rp 0.873; 总酚 SD-SPA Rp 0.973"],
    ], [18, 82]));
  out.push(body([bt("这篇论文的模型传递部分(表 3-23/3-24: 从仪器直接预测 Rp 低至 0.136~0.467, 经 DS/PDS 校正后恢复到 0.855~0.937)与本解析第 5.5 节的玉米跨仪器实验结论一致, 相互印证。它还有一条对本设计直接有用的经验: 籽粒直接测量不用粉碎、样品可复用, 但散射干扰显著, 必须靠散射校正或模型传递弥补——这正是黑青稞整粒检测要面对的问题。")]));

  out.push(h2("1.3　两篇论文的方法框架对比"));
  out.push(...dataTable("表 1-4　方法框架对比(也是你的毕业设计可选菜单)",
    ["环节", "杨焰婷 2024", "李苓蕾 2025", "本解析复现采用"],
    [
      ["异常剔除", "马氏距离(剔 4 个)", "未提及", "马氏距离(PCA 降维实现)"],
      ["样本划分", "SPXY 3:2", "SPXY 4:1", "SPXY 3:2(按杨文)"],
      ["预处理", "SG/SNV/MSC/SG+MSC/MSC+SNV", "SNV/MSC/Nor/DE/FD/SD", "同杨文 6 种"],
      ["特征筛选", "CARS/SPA/VCPA-IRIV", "CARS/SPA/UVE/LAR", "CARS + SPA(简化版)"],
      ["建模", "PLS", "PLS", "PLS(NIPALS 自实现)"],
      ["样本量", "76", "120", "76(仿真)"],
    ], [14, 30, 28, 28]));
  return out;
}

